import {calculateDemand} from './engine.js';
export const FIELD_SCHEMA=[
 {key:'population',target:'site',label:'Population used for planning',unit:'people',min:0,max:10000000,question:'What population estimate should this assessment use?',help:'Check local records or estimate occupancy. The geographic population layer is an estimate; retain its original value.',factor:[.7,1.3]},
 {key:'peoplePerHousehold',target:'inputs',label:'Average people per household',unit:'people / household',min:1,max:20,question:'How many people typically share a household here?',help:'Use an anonymous aggregate estimate or local records. The inconsistent survey household-size field is not used.',factor:[.7,1.4]},
 {key:'connectionPercent',target:'inputs',label:'Initial household connection uptake',unit:'%',min:0,max:100,question:'What share of households is expected to connect at launch?',help:'Record an estimate or aggregate expression of interest. Interest does not guarantee a future connection.',factor:[.5,1.4]},
 {key:'householdKWhPerMonth',target:'inputs',label:'Household monthly energy assumption',unit:'kWh / connected household / month',min:0,max:2000,question:'What monthly household-use assumption is supported by an appliance inventory or comparable-site evidence?',help:'Unelectrified households cannot report future metered use. Treat appliance-based or interview-derived figures as estimates.',factor:[.5,1.5]},
 {key:'millCount',target:'inputs',label:'Connected grain mills',unit:'mills',min:0,max:100000,integer:true,question:'How many grain mills are proposed or confirmed for connection?',help:'Separate proposed businesses from confirmed operating businesses. Zero in the original scenario is not proof of absence.',count:true},
 {key:'millHoursPerDay',target:'inputs',label:'Mill equivalent full-power hours',unit:'hours / operating day',min:0,max:24,question:'How many equivalent full-power hours would each mill run on an operating day?',help:'Check with the operator or equipment record. Energy hours do not describe starting surge or instantaneous peak.',hours:true},
 {key:'millDaysPerMonth',target:'inputs',label:'Mill operating days',unit:'days / 30-day model month',min:0,max:30,question:'How many days in a typical 30-day month would the mills operate?',help:'Account for weekly closure, maintenance and seasonal work. This is a representative-month assumption.',factor:[.6,1.2]},
 {key:'refrigerationCount',target:'inputs',label:'Connected refrigeration units',unit:'units',min:0,max:100000,integer:true,question:'How many refrigeration units are proposed or confirmed for connection?',help:'Confirm equipment type and equivalent compressor running time separately.',count:true},
 {key:'schoolCount',target:'inputs',label:'Connected schools',unit:'schools',min:0,max:100000,integer:true,question:'How many mapped schools should be included as connected loads?',help:'Mapped facilities are not automatically connected. Confirm operational status and intended connection.',count:true},
 {key:'clinicCount',target:'inputs',label:'Connected clinics',unit:'clinics',min:0,max:100000,integer:true,question:'How many clinics should be included as connected loads?',help:'Confirm whether the clinic is operating and whether it has an existing power source.',count:true}
];
export const EVIDENCE_METHODS={planned:'Planning assumption',reported:'Reported estimate',counted:'Counted on site',record:'Local / operator record',demo:'Demonstration response'};
const clone=x=>JSON.parse(JSON.stringify(x));
const cleanNumber=(value,f)=>{if(value===null||value===undefined||String(value).trim()==='')throw new Error(f.label+': enter a number or leave this answer unset.');const n=Number(value);if(!Number.isFinite(n)||n<f.min||n>f.max||(f.integer&&!Number.isInteger(n)))throw new Error(f.label+': use '+(f.integer?'a whole number':'a number')+' from '+f.min+' to '+f.max+'.');return n;};
export function createAssessment(context,id,now=new Date().toISOString()){
 if(!context.site||!context.inputs)throw new Error('Choose a village before starting an assessment.');
 return {schemaVersion:1,id:id||'assessment-'+Date.now(),siteId:String(context.site.id),siteName:String(context.site.name),createdAt:now,updatedAt:now,status:'draft',baseline:{site:clone(context.site),inputs:clone(context.inputs),mlSource:clone(context.mlSource||null),profileProvenance:clone(context.profileProvenance||null)},answers:{}};
}
export function setAnswer(record,key,value,method='planned',observedOn='',note='',now=new Date().toISOString()){
 const f=FIELD_SCHEMA.find(x=>x.key===key);if(!f)throw new Error('Unknown assessment field.');if(!Object.hasOwn(EVIDENCE_METHODS,method))throw new Error('Choose a listed evidence method.');if(key==='householdKWhPerMonth'&&method==='counted')throw new Error('Household energy needs an estimate or record; it cannot be labelled a field count.');
 if(observedOn&&!/^\d{4}-\d{2}-\d{2}$/.test(observedOn))throw new Error('Observation date must use YYYY-MM-DD.');
 if(observedOn){const parsed=new Date(observedOn+'T00:00:00Z');if(!Number.isFinite(parsed.valueOf())||parsed.toISOString().slice(0,10)!==observedOn||observedOn>now.slice(0,10))throw new Error('Use a valid observation date that is not in the future.');}
 const next=clone(record);next.answers[key]={value:cleanNumber(value,f),method,observedOn:observedOn||null,note:String(note||'').trim().slice(0,400),recordedAt:now};next.updatedAt=now;next.status='draft';delete next.appliedAt;return next;
}
export function removeAnswer(record,key,now=new Date().toISOString()){const next=clone(record);delete next.answers[key];next.updatedAt=now;next.status='draft';delete next.appliedAt;return next;}
export function assessmentValues(record){const site=clone(record.baseline.site),inputs=clone(record.baseline.inputs);for(const [key,a]of Object.entries(record.answers||{})){const f=FIELD_SCHEMA.find(x=>x.key===key);if(!f)throw new Error('Unknown assessment field.');(f.target==='site'?site:inputs)[key]=cleanNumber(a.value,f);}return {site,inputs};}
export function summarize(result){return {monthlyKWh:result.firstMonth.totalKWh,dailyKWh:result.firstMonth.dailyKWh,peakKW:result.firstMonth.peakKW,loadFactor:result.firstMonth.loadFactor,connections:result.firstMonth.connections,month24KWh:result.monthly[23].totalKWh};}
export function compareAssessment(record,profiles={}){const after=assessmentValues(record),beforeResult=calculateDemand(record.baseline.site,record.baseline.inputs,profiles),afterResult=calculateDemand(after.site,after.inputs,profiles);return {before:summarize(beforeResult),after:summarize(afterResult),deltaKWh:afterResult.firstMonth.totalKWh-beforeResult.firstMonth.totalKWh,changes:Object.entries(record.answers||{}).map(([key,a])=>{const f=FIELD_SCHEMA.find(x=>x.key===key);return {key,label:f.label,unit:f.unit,before:record.baseline[f.target][key],after:a.value,method:a.method,methodLabel:EVIDENCE_METHODS[a.method],observedOn:a.observedOn,note:a.note};}),scope:'Sensitivity-based scenario revision; no measured forecast improvement or calibrated village interval.'};}
export function rankQuestions(record,profiles={}){
 const current=assessmentValues(record),base=calculateDemand(current.site,current.inputs,profiles).firstMonth.totalKWh;
 return FIELD_SCHEMA.map(f=>{const value=Number(current[f.target][f.key]||0);let low,high;if(f.count){low=Math.max(0,value-1);high=value+1;}else if(f.hours){low=Math.max(0,value*.5);high=Math.min(24,Math.max(6,value*1.5));}else{low=value*f.factor[0];high=value*f.factor[1];if(value===0)high=f.key==='population'?Math.max(100,Number(current.site.buildings||0)*4.5):f.key==='connectionPercent'?25:f.key==='householdKWhPerMonth'?20:Math.max(1,f.min);}
 low=Math.max(f.min,Math.min(f.max,low));high=Math.max(f.min,Math.min(f.max,high));if(f.integer){low=Math.floor(low);high=Math.ceil(high);}const run=v=>{const site={...current.site},inputs={...current.inputs};(f.target==='site'?site:inputs)[f.key]=v;return calculateDemand(site,inputs,profiles).firstMonth.totalKWh;};const a=run(low),b=run(high);return {...f,value,low,high,lowEnergy:a,highEnergy:b,swingKWh:Math.abs(b-a),baseKWh:base,answered:Object.hasOwn(record.answers||{},f.key)};}).sort((a,b)=>Number(a.answered)-Number(b.answered)||b.swingKWh-a.swingKWh);
}
export function buildPassport(context){const s=context.sourceSite||context.site,current=context.site,i=context.inputs,e=context.fieldEvidence,manual=Boolean(s.manual);const rows=[];
 const add=(key,label,value,unit,kind,source,date,detail)=>rows.push({key,label,value,unit,kind,source,date:date||'Not recorded',detail});
 add('source_population','Source population',s.population,'people',manual?'User-entered':'Satellite / geospatial',manual?'Manual site entry':'Lamwo village_data.csv','', manual?'User-entered population; not satellite-extracted or independently verified.':'Raster-derived estimate. Fractional people are a model artifact, not a census count.');
 add('source_buildings','Source building count',s.buildings,'structures',manual?'User-entered':'Satellite / geospatial',manual?'Manual site entry':'Lamwo village_data.csv','', 'Structures are not occupied households. Not used directly in the demand calculation.');
 add('source_schools',manual?'Source schools':'Mapped schools',s.schools,'schools',manual?'User-entered':'Mapped reference',manual?'Manual site entry':'Lamwo educational_facilities','', manual?'User-entered facility count; operational status and connection have not been independently verified.':'Mapped records; operational status and connection have not been independently verified.');
 add('source_clinics',manual?'Source clinics':'Mapped clinics',s.clinics,'clinics',manual?'User-entered':'Mapped reference',manual?'Manual site entry':'Lamwo health_facilities','', 'Mapped records; operational status and connection have not been independently verified.');
 for(const f of FIELD_SCHEMA){const value=f.target==='site'?current[f.key]:i[f.key],a=e?.siteId===String(current.id)?e.answers?.[f.key]:null;const active=a&&Number(a.value)===Number(value);let kind='Assumed',source='Editable planning scenario',date='',detail=f.help;if(active){kind=a.method==='counted'?'Field count (user-declared)':a.method==='record'?'Record (user-declared)':a.method==='demo'?'Demonstration response':a.method==='reported'?'Reported estimate':'Assumed';source=EVIDENCE_METHODS[a.method]+' · assessment '+e.id;date=a.observedOn||'';detail=(a.note?a.note+' · ':'')+'Recorded '+a.recordedAt+'. User-declared evidence; not independently validated.';}else if(f.key==='population'&&Number(value)===Number(s.population)){kind=manual?'User-entered':'Satellite / geospatial';source=manual?'Manual site entry':'Lamwo village_data.csv';detail='Uses the original source estimate as a planning input. Its accuracy has not been independently established.';}else if(f.key==='householdKWhPerMonth'&&context.mlSource){kind='Survey-derived ML';source=context.mlSource.model_id;detail='Transferred household payment-proxy prediction. Historical bias and domain limits apply; not measured village demand.';}add(f.key,f.label,value,f.unit,kind,source,date,detail);}
 for(const [key,value] of Object.entries(i)){if(FIELD_SCHEMA.some(f=>f.key===key))continue;const label=key.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/^./,c=>c.toUpperCase());const unit=key.endsWith('KW')?'kW':key.endsWith('KWhPerDay')?'kWh / day':key.endsWith('HoursPerDay')?'equivalent hours / operating day':key.endsWith('DaysPerMonth')?'days / 30-day month':key.endsWith('Percent')?'% relative growth by month 24':key.endsWith('Count')?'connected units':'';add(key,label,value,unit,'Assumed','Editable planning scenario','', 'Explicit scenario parameter. No field verification or causal effect is established.');}
 for(const [key,value] of Object.entries(context.mlSource?.features||{})){const spec=context.mlSchema?.find(f=>f.name===key);const label=spec?.options?.find(o=>Number(o.value)===Number(value))?.label??value;add('ml_'+key,'ML profile — '+(spec?.label||key),label,'','Assumed ML profile',context.mlSource.flags?.includes('imputed_'+key)?'Training default':'Entered household scenario','', 'Profile transferred into the household survey-proxy model; not inferred from village imagery.');}
 add('model_month_days','Days per model month',30,'days','Assumed','Scenario engine','', 'Fixed model month; operating days are averaged within it.');
 add('low_multiplier','Low scenario multiplier',0.7,'× base energy','Assumed','Scenario engine','', 'Scenario envelope, not a calibrated probability interval.');
 add('high_multiplier','High scenario multiplier',1.35,'× base energy','Assumed','Scenario engine','', 'Scenario envelope, not a calibrated probability interval.');
 add('profile','Daily timing shapes',context.profileProvenance?.engine||'Explicit shapes','', 'Synthetic model',context.profileProvenance?.engine==='RAMP'?'RAMP '+context.profileProvenance.version:'Documented hourly assumptions','', 'Normalized timing only. Average-day peaks do not size equipment or motor surge.');
 return rows;
}
export function validateRecord(value){if(!value||value.schemaVersion!==1||typeof value.id!=='string'||typeof value.siteId!=='string'||!value.baseline?.site||!value.baseline?.inputs||!value.answers||Array.isArray(value.answers))throw new Error('Unsupported assessment record.');for(const [key,a]of Object.entries(value.answers)){const f=FIELD_SCHEMA.find(x=>x.key===key);if(!f||!a||!Object.hasOwn(EVIDENCE_METHODS,a.method)||(key==='householdKWhPerMonth'&&a.method==='counted'))throw new Error('Unsupported assessment answer.');cleanNumber(a.value,f);}return true;}
